type SliderRootState = {
    activeThumbIndex: number;
    disabled: boolean;
    dragging: boolean;
    max: number;
    min: number;
    minStepsBetweenValues: number;
    orientation: Orientation;
    step: number;
    values: number[];
    touched: boolean;
    dirty: boolean;
    valid: boolean | null;
    filled: boolean;
    focused: boolean;
};

